<?php
require_role(['admin','organisateur']);$base='index.php?page=competitions';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);
 if($action==='delete'){db()->prepare('DELETE FROM competitions WHERE id=?')->execute([$id]);flash('Compétition supprimée ainsi que ses épreuves et données associées.');redirect($base);}
 if($action==='save'){$data=[trim($_POST['name']??''),$_POST['event_date']??'',trim($_POST['venue']??''),max(1,min(10,(int)($_POST['lanes']??8))),($_POST['deadline']??'')?:null,$_POST['status']??'open'];if(!$data[0]||!$data[1]||!$data[2]||!in_array($data[5],['draft','open','running','finished'],true)){flash('Veuillez vérifier les champs.','error');}else{if($id){db()->prepare('UPDATE competitions SET name=?,event_date=?,venue=?,lanes=?,deadline=?,status=? WHERE id=?')->execute([...$data,$id]);flash('Compétition modifiée.');}else{db()->prepare('INSERT INTO competitions(name,event_date,venue,lanes,deadline,status) VALUES(?,?,?,?,?,?)')->execute($data);flash('Compétition créée.');}}redirect($base);}}
$edit=null;if(isset($_GET['edit'])){$q=db()->prepare('SELECT * FROM competitions WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
?>
<div class="grid2"><section class="panel"><h3><?=$edit?'Modifier la compétition':'Créer une compétition'?></h3><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><label>Nom</label><input name="name" required value="<?=e($edit['name']??'')?>"><label>Date</label><input type="date" name="event_date" required value="<?=e($edit['event_date']??'')?>"><label>Lieu / piscine</label><input name="venue" required value="<?=e($edit['venue']??'')?>"><label>Nombre de couloirs</label><input type="number" min="1" max="10" name="lanes" value="<?=e($edit['lanes']??8)?>"><label>Date limite des engagements</label><input type="date" name="deadline" value="<?=e($edit['deadline']??'')?>"><label>État</label><select name="status"><?php foreach(['draft'=>'Brouillon','open'=>'Ouverte','running'=>'En cours','finished'=>'Terminée'] as $k=>$v):?><option value="<?=$k?>" <?=($edit['status']??'open')===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select><button class="btn primary"><?= $edit?'Enregistrer les modifications':'Créer la compétition'?></button><?php if($edit):?> <a class="btn light" href="<?=$base?>">Annuler</a><?php endif;?></form></section>
<section class="panel"><h3>Compétitions enregistrées</h3><div class="table-wrap"><table><tr><th>Compétition</th><th>Date</th><th>Lieu</th><th>État</th><th>Actions</th></tr><?php foreach(db()->query('SELECT * FROM competitions ORDER BY event_date DESC') as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['event_date'])?></td><td><?=e($r['venue'])?></td><td><span class="pill"><?=e($r['status'])?></span></td><td class="actions"><a class="link" href="<?=$base?>&edit=<?=$r['id']?>">Modifier</a><form class="inline" method="post" onsubmit="return confirm('Supprimer cette compétition et toutes ses épreuves, engagements et résultats ?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="link danger">Supprimer</button></form></td></tr><?php endforeach;?></table></div></section></div>